def ico_bytes():
    return base64.b64decode("".join(ICO_B64))


def png_b64():
    return "".join(PNG_B64)


def write_ico(path):
    with open(path, "wb") as fh:
        fh.write(ico_bytes())
    return path


def image(size=64):
    from PIL import Image
    return Image.open(io.BytesIO(base64.b64decode(png_b64()))).convert("RGBA").resize((size, size), Image.LANCZOS)


def with_dot(size, color):
    from PIL import ImageDraw
    im = image(size)
    r = int(size * 0.17)
    ImageDraw.Draw(im).ellipse([size - 2 * r - 1, size - 2 * r - 1, size - 1, size - 1], fill=color,
                               outline=(255, 255, 255, 255), width=max(1, size // 20))
    return im


def install_tk():
    import tkinter
    init = tkinter.Tk.__init__

    def _init(self, *a, **k):
        init(self, *a, **k)
        try:
            self._tcsc_icon = tkinter.PhotoImage(master=self, data=png_b64())
            self.iconphoto(True, self._tcsc_icon)
        except Exception:
            pass
    tkinter.Tk.__init__ = _init
